"""Private, English-only recovery review with no external browser resources."""
import html
import secrets
from .customer_workspace_pearl import pearl_response

from fastapi.responses import HTMLResponse


def page(workspace_id):
    nonce = secrets.token_urlsafe(24)
    policy = ("default-src 'none'; script-src 'nonce-" + nonce + "'; style-src 'nonce-" + nonce
              + "'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
    source = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Account recovery | Agent Concierge</title><meta name="description" content="Review private organization recovery and pending requests."><style nonce="NONCE">
:root{color-scheme:light dark;font:16px/1.6 system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:light-dark(#f5f7fb,#10151e);color:light-dark(#182131,#edf2fa)}main{max-width:52rem;margin:auto;padding:2rem 1rem}section{padding:1.5rem;border:1px solid #8492a640;border-radius:1.25rem;margin:1rem 0;background:light-dark(#fff,#18202d)}h1{display:flex;gap:.6rem;align-items:center;font-size:1.8rem}h2{font-size:1.15rem}svg{width:1.7rem;height:1.7rem;flex:none}label{display:block;margin:.8rem 0}input,select,button,a{font:inherit;color:inherit}input:not([type=checkbox]),select{width:100%;padding:.65rem;border:1px solid #8492a680;border-radius:.6rem;background:transparent}button{padding:.65rem 1rem;margin:.3rem .3rem .3rem 0;border:1px solid #8492a680;border-radius:.6rem;background:light-dark(#edf3ff,#24334d);cursor:pointer}button:disabled{opacity:.5;cursor:default}a{color:light-dark(#2458b8,#96b8ff)}:focus-visible{outline:3px solid #5c9aff;outline-offset:3px}[hidden]{display:none!important}li{overflow-wrap:anywhere;padding:.8rem 0;border-bottom:1px solid #8492a640}#status{min-height:2rem}small{display:block;opacity:.8}.reference{font-family:ui-monospace,monospace;overflow-wrap:anywhere}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}</style></head><body><main>
<a href="/customer/organizations">Your organizations</a><h1><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11"/><path d="m9 12 2 2 4-4"/></svg>Account recovery</h1><p>Recovery requires a previously enrolled offline key and independent review. A request never grants immediate access. Current owners can contest it during the 24-hour review period.</p><p id="status" role="status" aria-live="polite">Checking your session.</p><input type="hidden" id="workspace" value="WORKSPACE">
<section id="owner" hidden><h2>Protect sole ownership</h2><p id="enrollment-state"></p><label>Offline recovery public key<input id="public-key" maxlength="43" autocomplete="off" spellcheck="false"></label><small>Enter only the public key. Keep the private key offline.</small><label>Independent review authority<select id="authority"></select></label><label><input type="checkbox" id="enroll-consent"> I understand that both proofs and a review period are required.</label><button id="enroll">Save recovery enrollment</button><button id="revoke">Withdraw enrollment</button><h2>Pending requests</h2><ul id="pending"></ul><button id="owner-refresh">Refresh requests</button></section>
<section><h2>Request recovery</h2><label>Reviewed evidence reference (SHA-256)<input id="evidence" autocomplete="off" spellcheck="false" maxlength="64"></label><button id="challenge">Prepare recovery request</button><a id="download" hidden download="recovery-review.json">Download request for independent review</a><p>Your evidence stays with your reviewer. Only its reference is recorded here.</p><label>Request reference<input id="request" maxlength="80" autocomplete="off" spellcheck="false"></label><label>Offline key signature<input id="owner-proof" maxlength="128" autocomplete="off" spellcheck="false"></label><label>Independent review signature<input id="review-proof" maxlength="128" autocomplete="off" spellcheck="false"></label><button id="submit">Submit reviewed proofs</button><p id="request-state"></p><button id="refresh">Check request</button><button id="withdraw">Withdraw request</button><button id="finalize">Complete recovery</button><small>Recheck the current request before completing recovery. Previous sessions and access will be withdrawn.</small></section>
</main><script nonce="NONCE">
const $=id=>document.getElementById(id),base='/api/customer-auth/organizations/'+encodeURIComponent($('workspace').value)+'/recovery';let csrf=null,revision=0,busy=false,downloadUrl=null,currentRequest=null,sessionReady=false;
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(body===undefined?15000:90000),headers:body===undefined?{}:{'Content-Type':'application/json','X-Customer-CSRF':csrf},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error('The request could not be confirmed. Refresh its current state before trying again.');return r.json()}
async function work(action){if(busy)return;busy=true;const finish=window.workspaceUI.begin('Processing your reviewed request…');document.querySelectorAll('main button').forEach(b=>b.disabled=true);try{await window.workspaceUI.paint();await action()}catch(e){$('status').textContent=e.message}finally{finish();busy=false;document.querySelectorAll('main button').forEach(b=>b.disabled=false);syncRecovery()}}
const requestPath=()=>base+'/requests/'+encodeURIComponent($('request').value);
function result(v){currentRequest=v;syncRecovery();$('request-state').textContent='Request status: '+v.status+(v.status==='pending'&&v.eligible_after?' · Review ends '+new Date(v.eligible_after*1000).toLocaleString('en'): '');$('status').textContent=v.access_granted?'Recovery completed. Enroll a new offline key.':'Current request checked.'}
function syncRecovery(){$('challenge').disabled=busy||!sessionReady||!/^[a-fA-F0-9]{64}$/.test($('evidence').value);$('submit').disabled=busy||!sessionReady||!$('request').value.trim()||!$('owner-proof').value.trim()||!$('review-proof').value.trim();$('refresh').disabled=$('withdraw').disabled=busy||!sessionReady||!$('request').value.trim();$('finalize').disabled=busy||!sessionReady||!currentRequest||currentRequest.status!=='pending'||!(currentRequest.eligible_after<=Date.now()/1000);$('enroll').disabled=busy||!sessionReady||!$('enroll-consent').checked||!$('authority').value||!$('public-key').value.trim()}
for(const id of ['evidence','request','owner-proof','review-proof','enroll-consent','authority','public-key'])$(id).addEventListener('input',()=>{if(id==='request')currentRequest=null;syncRecovery()});
async function owner(){const v=(await api(base)).result;revision=v.revision;$('owner').hidden=false;$('enrollment-state').textContent=v.enrolled?'Recovery enrollment is active.':'No current recovery enrollment.';$('authority').replaceChildren();for(const id of v.authorities){const o=document.createElement('option');o.value=id;o.textContent=id;$('authority').append(o)}$('pending').replaceChildren();for(const p of v.pending){const li=document.createElement('li'),ref=document.createElement('span'),button=document.createElement('button');ref.textContent=p.id+' · '+p.status;ref.className='reference';button.type='button';button.textContent='Contest request';button.onclick=()=>work(async()=>{await api(base+'/requests/'+encodeURIComponent(p.id)+'/contest',{});await owner();$('status').textContent='The request is contested. Access was not granted.'});li.append(ref,button);$('pending').append(li)}if(!v.pending.length){const li=document.createElement('li');li.textContent='No pending recovery requests.';$('pending').append(li)}}
$('owner-refresh').onclick=()=>work(owner);$('enroll').onclick=()=>work(async()=>{if(!$('enroll-consent').checked)throw Error('Review and confirm the recovery requirements.');await api(base+'/enrollment',{public_key:$('public-key').value,authority_id:$('authority').value,revision,authorized:true,notice:'customer-recovery-enroll-v1'});$('enroll-consent').checked=false;await owner();$('status').textContent='Recovery enrollment saved.'});$('revoke').onclick=()=>work(async()=>{await api(base+'/enrollment/withdraw',{revision});await owner();$('status').textContent='Recovery enrollment withdrawn.'});
$('challenge').onclick=()=>work(async()=>{currentRequest=null;const v=(await api(base+'/challenges',{evidence_sha256:$('evidence').value})).result;$('request').value=v.claim.id;if(downloadUrl)URL.revokeObjectURL(downloadUrl);downloadUrl=URL.createObjectURL(new Blob([JSON.stringify(v.claim)],{type:'application/json'}));$('download').href=downloadUrl;$('download').hidden=false;$('status').textContent='Request prepared. Submit both signatures by '+new Date(v.claim.proof_submission_expires*1000).toLocaleString('en')+'. Obtain a fresh request if this submission window expires.'});
$('submit').onclick=()=>work(async()=>{result((await api(requestPath()+'/proofs',{owner_signature:$('owner-proof').value,authority_signature:$('review-proof').value})).result);$('owner-proof').value='';$('review-proof').value=''});$('refresh').onclick=()=>work(async()=>result((await api(requestPath())).result));for(const action of ['withdraw','finalize'])$(action).onclick=()=>work(async()=>result((await api(requestPath()+'/'+action,{})).result));
(async()=>{try{csrf=(await api('/api/customer-auth/session')).session.csrf_token;sessionReady=true;document.dispatchEvent(new Event('workspace-session-ready'));$('status').textContent='Review recovery access and pending requests.';try{await owner()}catch{}syncRecovery()}catch{$('status').textContent='Sign in before requesting or reviewing recovery.';document.querySelectorAll('main button').forEach(b=>b.disabled=true)}})();window.addEventListener('pageshow',event=>{if(event.persisted)location.reload()});window.addEventListener('pagehide',()=>{if(downloadUrl)URL.revokeObjectURL(downloadUrl);csrf=null});
</script></body></html>'''.replace('NONCE', nonce).replace('WORKSPACE', html.escape(workspace_id, quote=True))
    return pearl_response(HTMLResponse(source, headers={'Cache-Control': 'no-store', 'Content-Security-Policy': policy,
        'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer',
        'X-Frame-Options': 'DENY', 'X-Robots-Tag': 'noindex,noarchive'}), nonce, section='account', workspace=workspace_id)
